-- HADI L'SHI (company_id 1), June 2026: safe original-source correction PART 1 ONLY.
-- Apply ONLY after making a database backup. Run as ONE full SQL statement in TablePlus with Auto-commit ON.
-- This does not eliminate the remaining $86,600 June credit (#17518). Do not manually delete that journal.
-- Single PostgreSQL statement: atomic (all changes succeed or none do). NEVER run fragments.
-- Expected result PASS HADI JUNE PART 1 - ORIGINAL VOUCHERS, 1, 1, 1, 1, 4, 6, 1.
-- Expected June Rent Expense #1007 after application: $127,550 Dr / $86,600 Cr = $40,950 Dr.
-- Keeps all original SAFE cash counterpart rows and audit history. Does not create any new vouchers.
WITH ctx AS MATERIALIZED ( SELECT set_config('app.current_company_id','1',true) tenant, set_config('app.company_scope_maintenance','off',true) maintenance ), guard AS MATERIALIZED ( SELECT current_database()='erp_db_qscj_64lv_e7rz_8744_2lm3' AND ctx.tenant='1' AND ctx.maintenance='off' AND EXISTS (SELECT 1 FROM companies WHERE id=1 AND name='HADI L''SHI' AND active) AND NOT EXISTS (SELECT 1 FROM fiscal_period_closures WHERE company_id=1 AND status='CLOSED' AND period_end_date>=DATE '2026-01-01') AND NOT EXISTS (SELECT 1 FROM audit_log WHERE company_id=1 AND user_id='system:hadi-june-2026-original-sources-part1-20261110' AND action='repair') AND (SELECT COUNT(*) FROM ledger_accounts WHERE company_id=1 AND id IN (881,1007,1021,1022,4282) AND deleted_at IS NULL AND COALESCE(opening_balance,0)=0)=5 AND NOT EXISTS (SELECT 1 FROM voucher_entries e JOIN vouchers v ON v.id=e.voucher_id AND v.company_id=e.company_id WHERE e.company_id=1 AND e.ledger_account_id=881 AND v.deleted_at IS NULL AND v.optional=false) AND (SELECT COUNT(*) FROM vouchers WHERE company_id=1 AND id IN (8565,8586,8790,17511) AND voucher_type='Journal' AND deleted_at IS NULL AND optional=false AND currency='USD')=4 AND (SELECT COUNT(*) FROM vouchers WHERE company_id=1 AND id=8789 AND voucher_type='Payment' AND voucher_date=DATE '2026-06-05' AND total_amount=4200 AND currency='USD' AND optional=false AND deleted_at IS NULL)=1 AND (SELECT COUNT(*) FROM vouchers WHERE company_id=1 AND id=8870 AND voucher_type='Payment' AND voucher_date=DATE '2026-06-08' AND total_amount=31500 AND currency='USD' AND optional=false AND deleted_at IS NULL)=1 AND (SELECT COUNT(*) FROM vouchers WHERE company_id=1 AND id=8565 AND voucher_date=DATE '2026-06-02' AND total_amount=96000)=1 AND (SELECT COUNT(*) FROM vouchers WHERE company_id=1 AND id=8586 AND voucher_date=DATE '2026-06-02' AND total_amount=96000)=1 AND (SELECT COUNT(*) FROM vouchers WHERE company_id=1 AND id=8790 AND voucher_date=DATE '2026-06-05' AND total_amount=4200)=1 AND (SELECT COUNT(*) FROM vouchers WHERE company_id=1 AND id=17511 AND voucher_date=DATE '2026-06-08' AND total_amount=31500)=1 AND (SELECT COUNT(*) FROM vouchers WHERE company_id=1 AND id=17518 AND voucher_date=DATE '2026-06-30' AND total_amount=86600 AND deleted_at IS NULL AND optional=false)=1 AND (SELECT COUNT(*) FROM voucher_entries WHERE company_id=1 AND voucher_id=8789)=2 AND (SELECT COUNT(*) FROM voucher_entries WHERE company_id=1 AND voucher_id=8870)=2 AND (SELECT COUNT(*) FROM voucher_entries WHERE company_id=1 AND id=30202 AND voucher_id=8789 AND ledger_account_id=1007 AND debit_amount=4200 AND credit_amount=0)=1 AND (SELECT COUNT(*) FROM voucher_entries WHERE company_id=1 AND id=30203 AND voucher_id=8789 AND ledger_account_id=112 AND debit_amount=0 AND credit_amount=4200)=1 AND (SELECT COUNT(*) FROM voucher_entries WHERE company_id=1 AND id=30535 AND voucher_id=8870 AND ledger_account_id=1007 AND debit_amount=31500 AND credit_amount=0)=1 AND (SELECT COUNT(*) FROM voucher_entries WHERE company_id=1 AND id=30536 AND voucher_id=8870 AND ledger_account_id=112 AND debit_amount=0 AND credit_amount=31500)=1 AND (SELECT md5(string_agg(e.id::text||':'||e.ledger_account_id::text||':'||e.debit_amount::text||':'||e.credit_amount::text,'|' ORDER BY e.id)) FROM voucher_entries e WHERE e.company_id=1 AND e.voucher_id=8565)='d2d9b58f22644be93e5f487f9a444d1d' AND (SELECT md5(string_agg(e.id::text||':'||e.ledger_account_id::text||':'||e.debit_amount::text||':'||e.credit_amount::text,'|' ORDER BY e.id)) FROM voucher_entries e WHERE e.company_id=1 AND e.voucher_id=8586)='fdc25b7c7e1f51ee2f60652552440b92' AND (SELECT md5(string_agg(e.id::text||':'||e.ledger_account_id::text||':'||e.debit_amount::text||':'||e.credit_amount::text,'|' ORDER BY e.id)) FROM voucher_entries e WHERE e.company_id=1 AND e.voucher_id=8790)='9ee72b38135458724c71e63e448a7ab8' AND (SELECT md5(string_agg(e.id::text||':'||e.ledger_account_id::text||':'||e.debit_amount::text||':'||e.credit_amount::text,'|' ORDER BY e.id)) FROM voucher_entries e WHERE e.company_id=1 AND e.voucher_id=17511)='6ac1759cdb704a247885deb30a13731e' AND NOT EXISTS (SELECT 1 FROM property_monthly_ledger WHERE company_id=1 AND accrual_voucher_id IN(8565,8586,8790,17511)) AND NOT EXISTS (SELECT 1 FROM property_payments WHERE company_id=1 AND voucher_id IN(8565,8586,8790,17511)) AND NOT EXISTS (SELECT 1 FROM cost_center_allocations c JOIN voucher_entries e ON e.id=c.voucher_entry_id WHERE e.company_id=1 AND e.voucher_id IN(8565,8586,8790,17511,8789,8870)) AND (SELECT COALESCE(SUM(e.debit_amount),0) FROM voucher_entries e JOIN vouchers v ON v.id=e.voucher_id AND v.company_id=e.company_id WHERE e.company_id=1 AND e.ledger_account_id=1007 AND v.deleted_at IS NULL AND v.optional=false AND v.voucher_date>=DATE '2026-06-01' AND v.voucher_date<DATE '2026-07-01')=259250 AND (SELECT COALESCE(SUM(e.credit_amount),0) FROM voucher_entries e JOIN vouchers v ON v.id=e.voucher_id AND v.company_id=e.company_id WHERE e.company_id=1 AND e.ledger_account_id=1007 AND v.deleted_at IS NULL AND v.optional=false AND v.voucher_date>=DATE '2026-06-01' AND v.voucher_date<DATE '2026-07-01')=218300 AND (SELECT COALESCE(SUM(e.debit_amount-e.credit_amount),0) FROM voucher_entries e JOIN vouchers v ON v.id=e.voucher_id AND v.company_id=e.company_id WHERE e.company_id=1 AND e.ledger_account_id=1007 AND v.deleted_at IS NULL AND v.optional=false)=434350 AS ok FROM ctx ), move_8789 AS (UPDATE voucher_entries SET ledger_account_id=1021 WHERE company_id=1 AND id=30202 AND voucher_id=8789 AND ledger_account_id=1007 AND debit_amount=4200 AND (SELECT ok FROM guard) RETURNING id), move_8870 AS (UPDATE voucher_entries SET ledger_account_id=1021,debit_amount=10500 WHERE company_id=1 AND id=30535 AND voucher_id=8870 AND ledger_account_id=1007 AND debit_amount=31500 AND (SELECT ok FROM guard) RETURNING id), new_prepaid AS (INSERT INTO voucher_entries(company_id,voucher_id,ledger_account_id,debit_amount,credit_amount,narration) SELECT 1,8870,1022,21000,0,'Original HADI #4 April-December payment #8870: July-December prepaid rent' FROM move_8870 RETURNING id), retired AS (UPDATE vouchers SET deleted_at=clock_timestamp(),description=description||' [SUPERSEDED: corrected original rent sources / zero-net accrual-release pair]' WHERE company_id=1 AND id IN(8565,8586,8790,17511) AND deleted_at IS NULL AND (SELECT COUNT(*) FROM move_8789)=1 AND (SELECT COUNT(*) FROM new_prepaid)=1 RETURNING id), audited AS (INSERT INTO audit_log(user_id,username,company_id,action,table_name,record_id,reason,changes) SELECT 'system:hadi-june-2026-original-sources-part1-20261110','system',1,'repair','vouchers',x.id,'HADI June rent original-source classification; original SAFE/cash untouched; redundant journal superseded',jsonb_build_object('source_voucher',x.id,'original_counterpart_unchanged',true,'phase','june-part-1-of-2') FROM (VALUES(8789),(8870),(8565),(8586),(8790),(17511)) x(id) WHERE (SELECT COUNT(*) FROM retired)=4 RETURNING id), counts AS (SELECT (SELECT COUNT(*) FROM move_8789) p1,(SELECT COUNT(*) FROM move_8870) p2,(SELECT COUNT(*) FROM new_prepaid) prepaid,(SELECT COUNT(*) FROM retired) retired,(SELECT COUNT(*) FROM audited) audited) SELECT CASE WHEN NOT guard.ok THEN 'NO CHANGES - JUNE SAFETY PRECHECK FAILED' WHEN counts.p1=1 AND counts.p2=1 AND counts.prepaid=1 AND counts.retired=4 AND counts.audited=6 THEN 'PASS HADI JUNE PART 1 - ORIGINAL VOUCHERS' ELSE 'ERROR - CHANGES ROLLED BACK' END result,guard.ok precheck_ok,counts.p1 source_8789_changed,counts.p2 source_8870_changed,counts.prepaid prepaid_added,counts.retired journals_superseded,counts.audited repair_audits,1/CASE WHEN NOT guard.ok OR (counts.p1=1 AND counts.p2=1 AND counts.prepaid=1 AND counts.retired=4 AND counts.audited=6) THEN 1 ELSE 0 END atomic_check FROM guard CROSS JOIN counts;
